    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create interface for TetherToken
        ITetherToken target = ITetherToken(TARGET);

        // Get the current owner
        address currentOwner = target.owner();
        console.log("Current owner:", currentOwner);

        // Get attacker's initial balance (attacker is address(this))
        uint256 initialAttackerBalance = target.balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // Impersonate the owner to call issue()
        vm.startPrank(currentOwner);

        // Mint a large amount of tokens to the owner
        // USDT has 6 decimals, so 1,000,000 * 1e6 = 1,000,000 USDT
        uint256 mintAmount = 1_000_000 * 10**target.decimals();
        target.issue(mintAmount);

        vm.stopPrank();

        // Now transfer the minted tokens from owner to attacker
        // First, approve attacker to spend owner's tokens
        vm.startPrank(currentOwner);
        target.approve(attacker, mintAmount);
        vm.stopPrank();

        // Then transfer from owner to attacker
        vm.startPrank(attacker);
        target.transferFrom(currentOwner, attacker, mintAmount);
        vm.stopPrank();

        // Check final balance
        uint256 finalAttackerBalance = target.balanceOf(attacker);
        console.log("Final attacker balance:", finalAttackerBalance);

        // Verify the exploit worked
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should have increased");
        console.log("Exploit successful! Balance increased by:", finalAttackerBalance - initialAttackerBalance);

        // Check ERC20 balance as well
        uint256 finalERC20Balance = IERC20(TARGET).balanceOf(address(this));
        uint256 initialERC20Balance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

